INSERT INTO public.design_templates VALUES
	('70000000-0000-4000-8000-000000000001', NULL, 'Moonlit Botanicals', 'system', 'Nature & Botanical', 'dark_academia', 'Create a centered, print-ready {style} illustration of {subject} for the {niche} niche. Frame the subject with {keywords}, lunar accents, and refined vintage linework. Use a near-black, bone, and muted botanical palette, a strong silhouette, and clean negative space. Isolated artwork, no product mockup.', '[{"prompt": "A symmetrical luna moth framed by yarrow, fern, and small lunar phases, rendered in bone ink on deep black.", "subject": "luna moth with wildflowers"}, {"prompt": "A centered raven above belladonna and foxglove, enclosed by a restrained moon-phase arch.", "subject": "raven among poisonous herbs"}]', 'Detailed moth and wildflower compositions for apparel and wall art.', '/images/design-templates/moonlit-botanicals.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'photorealism, glossy 3D render, busy background, muddy blacks, blurry edges, illegible text, logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000002', NULL, 'Desert Horizon', 'system', 'Outdoors', 'vintage', 'Create a print-ready {style} desert scene featuring {subject} for the {niche} niche. Weave in {keywords} as secondary motifs. Use a limited sun-faded palette, layered silhouettes, rugged halftone texture, and large screen-print-friendly shapes. Centered isolated artwork, no product mockup.', '[{"prompt": "A burnt-orange sun setting behind layered canyon silhouettes with a single winding trail.", "subject": "sunset over a winding canyon trail"}, {"prompt": "A tall saguaro and distant mesas framed by a faded crescent moon and sparse desert stars.", "subject": "saguaro beneath a crescent moon"}]', 'Warm retro landscapes with strong silhouettes for outdoor collections.', '/images/design-templates/desert-horizon.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'neon colors, glossy 3D, photorealistic landscape, thin unreadable details, crowded composition, logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000003', NULL, 'Coffee Geometry', 'system', 'Food & Drink', 'minimalist', 'Create a print-ready {style} composition of {subject} for the {niche} niche. Reduce {keywords} into simple geometric accents. Use clear negative space, balanced circles and lines, and a two-color high-contrast palette. Centered isolated artwork, no product mockup.', '[{"prompt": "A simple cup reduced to circles and arcs, with one calm ribbon of steam.", "subject": "a steaming coffee cup"}, {"prompt": "A centered moka pot built from clean geometric planes with three bean-shaped accents.", "subject": "a moka pot and coffee beans"}]', 'Clean geometric compositions for mugs, kitchen prints, and cafe gifts.', '/images/design-templates/coffee-geometry.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'busy background, photorealism, gradients, excessive detail, weak contrast, logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000004', NULL, 'Campfire Crest', 'system', 'Outdoors', 'vintage', 'Design a compact, print-ready {style} outdoor badge featuring {subject} for the {niche} niche. Integrate {keywords} around a clear central silhouette, rugged ink texture, and a limited heritage palette. Keep every shape legible at small sizes. Isolated emblem, no product mockup.', '[{"prompt": "A mountain, two pines, a tent, and a campfire arranged inside a circular badge.", "subject": "mountain campsite at dawn"}, {"prompt": "A canoe crossing still water beneath a compact pine-and-mountain crest.", "subject": "canoe beside a pine lake"}]', 'Badge-style camping artwork made for tees, stickers, and patches.', '/images/design-templates/campfire-crest.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'photograph, complex scenery, tiny text, thin outlines, glossy effects, logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000005', NULL, 'Blue Garden', 'system', 'Nature & Botanical', 'watercolor', 'Paint a print-ready {style} arrangement of {subject} for the {niche} niche. Blend {keywords} into airy stems and natural asymmetry, using translucent washes and a cool blue-green palette while keeping the central subject clear. Isolated artwork on a clean background, no product mockup.', '[{"prompt": "A loose bouquet of blue hydrangeas, white anemones, and sage leaves with open breathing space.", "subject": "anemones and hydrangeas"}, {"prompt": "Three blue irises balanced by curved eucalyptus stems and soft transparent shadows.", "subject": "blue iris and eucalyptus"}]', 'Soft floral arrangements for calm home, stationery, and wellness products.', '/images/design-templates/blue-garden.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'hard vector outlines, neon saturation, muddy washes, dense background, readable text, logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000006', NULL, 'Heritage Motorcycle', 'system', 'Vehicles', 'vintage', 'Create a print-ready {style} engraving of {subject} for the {niche} niche. Use {keywords} only as restrained mechanical accents, with confident black linework, crisp metal highlights, controlled cross-hatching, and no background clutter. Centered isolated artwork, no product mockup.', '[{"prompt": "A three-quarter cafe racer with accurate wheels, tank, and detailed engine linework.", "subject": "classic cafe racer motorcycle"}, {"prompt": "A centered scrambler with engraved metal detail, high exhaust pipes, and restrained ground shadow.", "subject": "vintage scrambler motorcycle"}]', 'Engraved mechanical illustrations for garage and rider collections.', '/images/design-templates/heritage-motorcycle.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'modern sport bike, color photograph, motion blur, distorted wheels, incorrect engine geometry, brand logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000007', NULL, 'Bold Rally', 'system', 'Quotes & Motivation', 'bold_typography', 'Create a print-ready {style} composition using the exact phrase "{subject}" for the {niche} niche. Preserve spelling and capitalization exactly. Build a dominant condensed sans-serif hierarchy, use {keywords} as small supporting motifs, and limit the artwork to two or three solid inks with strong alignment and generous negative space. Isolated artwork, no product mockup.', '[{"prompt": "Stack the exact phrase in three compact lines with a forward arrow cutting through the final word.", "subject": "KEEP MOVING FORWARD"}, {"prompt": "Use tall condensed lettering with a small four-leaf symbol and a strong centered baseline.", "subject": "MAKE YOUR OWN LUCK"}]', 'High-impact exact-text compositions for motivational apparel and posters.', '/images/design-templates/bold-rally.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'misspelled words, extra words, distorted letters, thin script, low contrast, photographic background, logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000008', NULL, 'Dry Humor Club', 'system', 'Humor & Lifestyle', 'funny_quote', 'Create a print-ready {style} merch graphic built around the exact phrase "{subject}" for the {niche} niche. Preserve spelling and capitalization exactly. Pair the quote with one simple deadpan illustration inspired by {keywords}; use chunky readable lettering, two or three flat inks, and generous negative space. Centered isolated artwork, no product mockup.', '[{"prompt": "Pair the exact quote with a tired coffee cup and a nearly empty battery icon.", "subject": "RUNNING ON COFFEE AND BAD IDEAS"}, {"prompt": "Place the exact quote around a deadpan cat sitting on a short stack of books.", "subject": "MY WEEKEND IS FULLY BOOKED"}]', 'Short deadpan quotes paired with simple, readable character art.', '/images/design-templates/dry-humor-club.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'long paragraph, misspelled text, offensive imagery, crowded scene, realistic photograph, tiny lettering, logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000009', NULL, 'Birth Month Blooms', 'system', 'Gifts & Occasions', 'floral', 'Create a print-ready {style} composition of {subject} for the {niche} niche. Weave in {keywords} as small botanical details. Use graceful stems, balanced bouquet or wreath spacing, clean outlines, and a limited natural palette. Centered isolated artwork, no product mockup.', '[{"prompt": "A balanced bouquet of carnations and snowdrops with curved stems and small winter leaves.", "subject": "January carnation and snowdrop bouquet"}, {"prompt": "An open circular wreath of roses and honeysuckle with a clean center for optional personalization.", "subject": "June rose and honeysuckle wreath"}]', 'Gift-ready floral structures for birth-month and occasion collections.', '/images/design-templates/birth-month-blooms.webp', true, true, 0, '2026-09-22 13:19:44.114338+00', '2026-11-07 16:59:21.432879+00', NULL, 'photorealistic flower photo, plastic texture, cluttered background, heavy shadows, neon palette, text, logo, watermark, product mockup'),
	('70000000-0000-4000-8000-000000000010', NULL, 'Wildflower Line Bouquet', 'system', 'Nature & Botanical', 'floral', 'Create a print-ready {style} t-shirt graphic of {subject} for the {niche} niche, gathered into a loose hand-drawn bouquet. Add {keywords} as small filler sprigs. Use confident medium-weight ink outlines that stay visible when printed 10 inches wide, with soft flat color fills in a muted terracotta, sage, mustard, and dusty pink palette. Keep stems tied together at the bottom, a tall vertical silhouette, and generous space between blooms. Designed for light garments. Centered isolated artwork on a plain solid white background, no shadows, no product mockup.', '[{"prompt": "A tall loose bouquet of daisies, red poppies, and lavender sprigs tied at the stems, flat muted fills with clear ink outlines.", "subject": "daisies, poppies, and lavender"}, {"prompt": "California poppies, lupine, and baby blue eyes gathered into a narrow bouquet with small grass sprigs.", "subject": "California wildflowers"}, {"prompt": "Airy cosmos blooms and queen anne''s lace in a balanced bouquet with a few curling leaves.", "subject": "cosmos and queen anne''s lace"}]', 'Hand-drawn wildflower bouquets with flat muted fills for cottagecore and botanical shirts.', NULL, true, true, 0, '2026-10-16 14:50:19.057675+00', '2026-11-07 16:59:29.231647+00', NULL, 'photorealistic flowers, watercolor bleed, gradient background, fading edges, hairline strokes, dense overlapping petals, text, t-shirt, mockup, fabric texture, checkerboard pattern, drop shadow, cropped subject, frame border, logo, watermark, signature'),
	('70000000-0000-4000-8000-000000000011', NULL, 'Game Day Mom', 'system', 'Sports & Fitness', 'bold_typography', 'Create a print-ready {style} t-shirt graphic using the exact phrase "{subject}" for the {niche} niche. Preserve spelling and capitalization exactly and render every letter once. Stack the words in two or three lines of heavy condensed varsity lettering with a slight upward arch on the top line, and integrate one matching sports ball or equipment icon beside or inside the lettering. Use {keywords} as small stitch lines, stars, or speed marks. Limit the artwork to two solid inks plus white outlines, high contrast, slightly distressed print texture. Designed for light garments. Centered isolated artwork on a plain solid white background, no product mockup.', '[{"prompt": "BASEBALL arched over a bold MOM, a baseball with red stitching tucked beside the M, navy and red inks.", "subject": "BASEBALL MOM"}, {"prompt": "SOCCER stacked above MAMA in condensed varsity letters with a small soccer ball and two speed marks, black and kelly green inks.", "subject": "SOCCER MAMA"}, {"prompt": "GAME DAY arched over VIBES with a football icon and small stars, brown and burnt orange inks.", "subject": "GAME DAY VIBES"}]', 'Stacked varsity lettering with one sport icon for team-parent and game-day shirts.', NULL, true, true, 0, '2026-10-16 14:50:19.057675+00', '2026-11-07 16:59:29.231647+00', NULL, 'misspelled text, extra letters, duplicated words, long sentence, thin script, tiny lettering, team names, league logos, player numbers, photorealistic ball, gradients, t-shirt, mockup, fabric texture, checkerboard pattern, drop shadow, cropped text, frame border, watermark, signature'),
	('70000000-0000-4000-8000-000000000012', NULL, 'One-Line Pet Portrait', 'system', 'Pets & Animals', 'minimalist', 'Create a print-ready {style} t-shirt graphic of {subject} for the {niche} niche, drawn as a continuous single-line portrait. Capture the breed through head shape, ears, and muzzle with as few strokes as possible, and add {keywords} as one small accent such as a heart, paw print, or collar tag. Use one uniform black line of medium weight that stays visible when printed 8 inches wide, with an optional single flat color spot behind the head. Keep the face recognizable, the composition compact, and plenty of negative space. Designed for light garments. Centered isolated artwork on a plain solid white background, no product mockup.', '[{"prompt": "A one-line golden retriever head with floppy ears and a small heart where the line ends, one soft mustard spot behind it.", "subject": "a golden retriever head"}, {"prompt": "A continuous-line tabby cat sitting with its tail curled around its paws and a tiny paw print accent.", "subject": "a sitting tabby cat"}, {"prompt": "A one-line french bulldog face with bat ears and a small collar tag, one dusty pink spot behind the head.", "subject": "a french bulldog face"}]', 'Minimal continuous-line pet portraits for dog mom, cat lady, and breed-lover shirts.', NULL, true, true, 0, '2026-10-16 14:50:19.057675+00', '2026-11-07 16:59:29.231647+00', NULL, 'photorealistic fur, shading, cross-hatching, multiple line weights, sketchy broken lines, full body scene, busy background, text, t-shirt, mockup, fabric texture, checkerboard pattern, drop shadow, cropped ears, frame border, logo, watermark, signature') ON CONFLICT DO NOTHING;
