	('all_video_formats', 'Landscape video', 'Render standard videos in landscape as well as square and portrait.', 'Video', 'flag', NULL, NULL, true, true, 60, '2026-11-07 16:59:28.718699+00', NULL, NULL),
	('ai_video', 'AI video (Veo)', 'Build videos from AI scenes, billed to the Seller''s own Google key.', 'Video', 'flag', NULL, NULL, false, true, 70, '2026-11-07 16:59:28.718699+00', NULL, NULL),
	('studio_keyframe', 'AI studio keyframes', 'Generate AI studio start frames for AI video scenes.', 'Video', 'flag', NULL, NULL, false, true, 80, '2026-11-07 16:59:28.718699+00', NULL, NULL),
	('daily_mockup_cap', 'Daily mockup safety cap', 'Most mockups rendered per day. Leave empty for no cap.', 'Safety caps', 'limit', 'per day', 300, true, true, 90, '2026-11-07 16:59:28.718699+00', NULL, NULL),
	('daily_listing_cap', 'Daily listing safety cap', 'Most listings generated per day. Leave empty for no cap.', 'Safety caps', 'limit', 'per day', 100, true, true, 100, '2026-11-07 16:59:28.718699+00', NULL, NULL),
	('daily_video_cap', 'Daily video safety cap', 'Most standard videos rendered per day. Leave empty for no cap.', 'Safety caps', 'limit', 'per day', 50, true, true, 110, '2026-11-07 16:59:28.718699+00', NULL, NULL),
	('workflow_listing', 'Listing content', 'Write listing titles, tags and descriptions, in a workflow or on their own.', 'Workflow', 'flag', NULL, NULL, true, true, 120, '2026-11-07 16:59:28.718699+00', NULL, NULL),
	('workflow_publish', 'Publish to Etsy and Printify', 'Publish finished products to Etsy and Printify, once those steps are available.', 'Workflow', 'flag', NULL, NULL, true, true, 130, '2026-11-07 16:59:28.718699+00', NULL, NULL),
	('design_images', 'Design images from prompt', 'Generate design images from a prompt, on their own or in a workflow.', 'Design images', 'flag', NULL, NULL, true, true, 5, '2026-11-07 16:59:41.182611+00', NULL, NULL),
	('template_mockups', 'Mockups from templates', 'Render mockups with the built-in templates.', 'Mockups', 'flag', NULL, NULL, true, true, 25, '2026-11-07 16:59:41.182611+00', NULL, NULL),
	('standard_video', 'Standard video', 'Render standard videos in square and portrait.', 'Video', 'flag', NULL, NULL, true, true, 55, '2026-11-07 16:59:41.182611+00', NULL, NULL),
	('zip_export', 'ZIP export', 'Download a finished product''s files as a ZIP.', 'Workflow', 'flag', NULL, NULL, true, true, 125, '2026-11-07 16:59:41.182611+00', NULL, NULL),
	('monthly_listings', 'Listings per month', 'Most listings a Seller can write each calendar month. Leave empty for no limit.', 'Listing', 'limit', 'per month', 10, true, true, 45, '2026-11-07 16:59:41.182611+00', NULL, NULL) ON CONFLICT DO NOTHING;
