INSERT INTO public.style_art_presets VALUES
	('a1d56ebe-36c1-4f37-a866-3cf98dba366b', 'Vintage', 'Warm retro film look with nostalgic tones, suited for apparel and posters with a classic feel.', 'vintage film photography, warm tones, subtle grain texture, soft retro lighting', NULL, '["Apparel graphics", "Retro posters", "Warm color palettes"]', true, true, 0, '2026-09-18 05:12:14.367598+00', '2026-09-18 05:12:14.367598+00', NULL),
	('2757abe2-f7e0-4288-90f2-ca12f95c8a24', 'Minimalist', 'Clean and airy composition with generous empty space, suited for modern brands and simple layouts.', 'minimalist composition, clean lines, ample negative space, soft neutral tones', NULL, '["Modern brands", "Simple layouts", "Logo-centric designs"]', true, true, 0, '2026-09-18 05:12:14.367598+00', '2026-09-18 05:12:14.367598+00', NULL),
	('67653cbc-c6d1-4ef3-be5b-ec3d05f03fe5', 'Watercolor', 'Soft painted look with fluid washes and gentle edges, suited for stationery and delicate artwork.', 'watercolor painting, soft brush strokes, fluid color washes, delicate edges', NULL, '["Stationery", "Floral artwork", "Soft color stories"]', true, true, 0, '2026-09-18 05:12:14.367598+00', '2026-09-18 05:12:14.367598+00', NULL),
	('2d9236c3-d525-4e0e-87b0-d59d7e3628fe', 'Oil Painting', 'Rich classical look with visible texture and dramatic light, suited for premium wall art.', 'classical oil painting, rich impasto texture, dramatic chiaroscuro lighting, deep colors', NULL, '["Wall art", "Premium prints", "Dramatic subjects"]', true, true, 0, '2026-09-18 05:12:14.367598+00', '2026-09-18 05:12:14.367598+00', NULL),
	('55e1dee3-9fc3-4bf6-a570-37efcd27de5e', 'Anime', 'Bold illustrated look with crisp lines and vivid colors, suited for stickers and youth apparel.', 'anime illustration style, cel shading, vibrant colors, clean line art', NULL, '["Stickers", "Youth apparel", "Character artwork"]', true, true, 0, '2026-09-18 05:12:14.367598+00', '2026-09-18 05:12:14.367598+00', NULL),
	('a6957938-31cd-4d9e-b889-1d882f074668', 'Photorealistic', 'Lifelike photographic detail with natural light, suited for mockups and realistic product scenes.', 'photorealistic, ultra detailed, natural lighting, sharp focus', NULL, '["Mockups", "Product scenes", "Realistic previews"]', true, true, 0, '2026-09-18 05:12:14.367598+00', '2026-09-18 05:12:14.367598+00', NULL) ON CONFLICT DO NOTHING;
