	('a1dc0c03-7336-4e24-a173-7a882e310004', 'Creator POV / UGC', 'ai_video_scene', 'etsy', 4, '9:16', '720p', '{"aiVideo": {"code": "creator_pov_ugc", "name": "Creator POV / UGC", "defaults": {"framing": "close_up", "lighting": "bright_clean", "cameraAngle": "eye_level", "templateCode": "creator_pov_ugc", "subjectMotion": "natural", "cameraMovement": "subtle_handheld", "durationSeconds": 4, "motionIntensity": "subtle"}, "basePrompt": "Create an authentic creator-style product demonstration featuring the adult already visible in the approved source image. Use a realistic phone-camera aesthetic in {{FRAMING}}, {{CAMERA_ANGLE}} composition. The camera uses {{CAMERA_MOVEMENT}} with controlled micro-movement. The creator naturally presents the exact product toward the camera without covering its artwork. {{LIGHTING}} Maintain candid UGC realism, accurate anatomy and stable product details. There is no dialogue, lip-sync or exaggerated performance. Create a {{DURATION}}-second shot.", "description": "An authentic creator-style product demonstration with a phone-camera feel.", "commonPrompt": "Use the approved source image as the primary visual reference. Keep the product recognizable by preserving its visible shape, main color, material character, proportions, and the placement of its artwork, logo and readable text. Let fabric or other materials, lighting, shadows, background and camera perspective move naturally when appropriate to the scene. Keep the product coherent over time; avoid duplicate products or conspicuous details that conflict with the source image. Create one continuous shot without cuts. Avoid unrelated text, watermarks and extra products. No dialogue, speech, singing or music; use quiet ambient room tone only.", "promptVersion": 2, "requiresDetail": false, "allowedSettings": {"framing": ["medium_close", "close_up"], "lighting": ["bright_clean", "warm_natural"], "cameraAngle": ["eye_level", "three_quarter"], "subjectMotion": ["minimal", "natural"], "cameraM