	('a1dc0c03-7336-4e24-a173-7a882e310003', 'Product On Model', 'ai_video_scene', 'etsy', 4, '9:16', '720p', '{"aiVideo": {"code": "lifestyle_in_use", "name": "Product On Model", "defaults": {"framing": "medium", "lighting": "warm_natural", "cameraAngle": "eye_level", "templateCode": "lifestyle_in_use", "subjectMotion": "minimal", "cameraMovement": "push_in", "durationSeconds": 4, "motionIntensity": "subtle", "subtemplateCode": "natural_motion"}, "basePrompt": "Create one continuous polished product-on-model fashion shot from the approved source image. Keep the model in the established pose and wearing the exact product. The camera performs {{CAMERA_MOVEMENT}} at {{CAMERA_ANGLE}} in {{FRAMING}} for the full {{DURATION}} seconds. The model subtly shifts their weight with restrained, natural body movement while the garment settles naturally across the torso. {{LIGHTING}} Use soft realistic shadows, shallow depth of field and subtle film grain. Keep the setting coherent and animate only background elements already visible in the source.", "description": "Fashion videos that keep the exact product naturally presented on the model.", "commonPrompt": "Use the approved source image as the authoritative reference. Keep the same model and exact product throughout the shot. Preserve the product''s visible fit, construction, colors, artwork, logos, lettering and placement; allow only natural changes caused by posture, fabric folds, perspective and brief occlusion. Keep anatomy and fabric motion realistic. Use one continuous shot with no cuts, morphing, duplicate people or products, wardrobe changes, added text, watermarks, dialogue or music.", "subtemplates": [{"code": "natural_motion", "name": "Natural Motion", "defaults": {"framing": "medium", "lighting": "warm_natural", "cameraAngle": "eye_level", "templateCode": "lifestyle_in_use", "subjectMotion": "minimal", "cameraMovement": "push_in", "durationSeconds": 4, "motionIntensity": "subtle", "subtemplateCode": "natural_motion"}, "basePrompt": "Create one continuous polished product-on-model fashion shot from the approved source image. Keep the model in the established pose and wearing the exact product. The camera performs {{CAMERA_MOVEMENT}} at {{CAMERA_ANGLE}} in {{FRAMING}} for the full {{DURATION}} seconds. The model subtly shifts their weight with restrained, natural body movement while the garment settles naturally across the torso. {{LIGHTING}} Use soft realistic shadows, shallow depth of field and subtle film grain. Keep the setting coherent and animate only background elements already visible in the source.", "description": "A balanced fashion shot with restrained model movement and a slow camera push.", "startFramePrompt": "Create a photorealistic medium eye-level fashion keyframe. The model faces mostly forward with a slight three-quarter turn, feet planted, relaxed shoulders and natural arms that do not cover the garment or artwork. Keep the full torso, product silhouette and visible design clear in warm editorial light."}, {"code": "fabric_detail", "name": "Fabric Detail Close-Up", "defaults": {"framing": "close_up", "lighting": "warm_natural", "cameraAngle": "three_quarter", "templateCode": "lifestyle_in_use", "subjectMotion": "minimal", "cameraMovement": "push_in", "durationSeconds": 4, "motionIntensity": "subtle", "subtemplateCode": "fabric_detail"}, "basePrompt": "Create one continuous editorial close-up of the exact garment on the model from the approved source image. Frame a construction or surface detail that is actually visible, such as fabric texture, a seam, stitching, collar, shoulder, or print edge; do not invent missing garment features. The camera performs {{CAMERA_MOVEMENT}} at {{CAMERA_ANGLE}} in {{FRAMING}} for the full {{DURATION}} seconds. Keep the model mostly still with subtle breathing and natural fabric settling. {{LIGHTING}} Let soft light reveal real texture, use shallow depth of field, and keep the selected product detail in precise focus.", "description": "A close editorial view that reveals only garment texture and construction visible in the source.", "startFramePrompt": "Create a photorealistic close editorial keyframe of the model wearing the exact product, cropped around the upper torso and a real fabric or artwork detail. Keep texture, stitching, print edges, lettering and colors sharp and unchanged. Use a slight three-quarter angle, soft natural light and no invented details."}, {"code": "brand_focus", "name": "Brand Focus", "defaults": {"framing": "medium", "lighting": "golden_hour", "cameraAngle": "eye_level", "templateCode": "lifestyle_in_use", "subjectMotion": "minimal", "cameraMovement": "push_in", "durationSeconds": 4, "motionIntensity": "subtle", "subtemplateCode": "brand_focus"}, "basePrompt": "Create one continuous medium product-on-model editorial shot from the approved source image. Use torso framing and keep the garment''s visible artwork, lettering, or logo as the visual focus; if the garment has no branding, emphasize its real silhouette, color blocking, and construction instead. The camera performs {{CAMERA_MOVEMENT}} at {{CAMERA_ANGLE}} in {{FRAMING}} for the full {{DURATION}} seconds. The model makes a small confident posture adjustment while keeping the product naturally visible. {{LIGHTING}} Preserve accessories only when they already exist in the source. Use natural fabric folds, warm commercial color, shallow depth of field, and restrained film grain.", "description": "A medium torso shot that keeps visible artwork, lettering, or the garment silhouette clear.", "startFramePrompt": "Create a photorealistic medium-close, eye-level fashion keyframe that is nearly front-facing. Center the garment artwork, logo or silhouette and keep it flat, readable and fully unobstructed. The model stands naturally with hands outside the product area, clean commercial light and a simple coherent background."}, {"code": "profile_tracking", "name": "Profile Tracking", "defaults": {"framing": "medium", "lighting": "golden_hour", "cameraAngle": "three_quarter", "templateCode": "lifestyle_in_use", "subjectMotion": "minimal", "cameraMovement": "gentle_tracking", "durationSeconds": 4, "motionIntensity": "subtle", "subtemplateCode": "profile_tracking"}, "basePrompt": "Create one continuous profile-tracking fashion shot from the approved source image. From the first frame, the camera tracks slowly sideways around the stationary model at a constant speed for the full {{DURATION}} seconds, with no opening hold or delayed movement. Keep the model rooted in place with feet planted: no walking, stepping or forward motion; allow only subtle breathing, a tiny weight shift without a step and minimal natural hand movement. Let the camera create a shallow three-quarter-to-profile change within the source-supported view while the garment artwork remains the visual focus and recognizable throughout. Use {{FRAMING}} at {{CAMERA_ANGLE}}. {{LIGHTING}} Use shallow depth of field and polished editorial color.", "description": "A slow side-oriented camera track around a stationary model.", "startFramePrompt": "Create a photorealistic medium eye-level fashion keyframe from a three-quarter side angle. The model stands still with feet planted, torso turned about 45 degrees, neutral head and relaxed arms away from the artwork. Keep enough garment front visible for the design and leave lateral space for an immediate sideways camera track. No walking pose."}], "promptVersion": 6, "requiresDetail": false, "allowedSettings": {"framing": ["wide", "medium", "medium_close", "close_up"], "lighting": ["warm_natural", "golden_hour", "bright_clean"], "cameraAngle": ["eye_level", "three_quarter"], "subjectMotion": ["minimal", "natural"], "cameraMovement": ["locked", "push_in", "gentle_tracking"], "motionIntensity": ["subtle", "balanced"]}, "requiresLifestyle": true, "defaultSubtemplateCode": "natural_motion"}}', NULL, true, true, '2026-10-16 13:34:49.536403+00', '2026-10-16 13:34:49.536403+00', 'lifestyle_in_use', 1),
