	('a1dc0c03-7336-4e24-a173-7a882e310002', 'Macro Detail Reveal', 'ai_video_scene', 'etsy', 4, '9:16', '720p', '{"aiVideo": {"code": "macro_detail_reveal", "name": "Macro Detail Reveal", "defaults": {"framing": "macro", "lighting": "soft_studio", "cameraAngle": "three_quarter", "templateCode": "macro_detail_reveal", "subjectMotion": "none", "cameraMovement": "pan_right", "durationSeconds": 4, "motionIntensity": "subtle"}, "basePrompt": "Create one continuous photorealistic macro commercial shot from the approved detail image. The selected {{CAMERA_MOVEMENT}} is the primary visible action and continues smoothly across the artwork for the full {{DURATION}} seconds from {{CAMERA_ANGLE}}, using {{FRAMING}}. Keep the focus plane locked to the printed surface so fine material texture, print edges and all visible lettering remain sharp and readable while the camera moves. {{LIGHTING}} Use controlled reflections without glare or focus hunting. Keep the artwork physically attached to the product. Camera motion intensity is {{MOTION_INTENSITY}}.", "description": "A close commercial view of the printed artwork and material texture.", "commonPrompt": "Use the approved source image as the primary visual reference. Keep the product recognizable by preserving its visible shape, main color, material character, proportions, and the placement of its artwork, logo and readable text. Let fabric or other materials, lighting, shadows, background and camera perspective move naturally when appropriate to the scene. Keep the product coherent over time; avoid duplicate products or conspicuous details that conflict with the source image. Create one continuous shot without cuts. Avoid unrelated text, watermarks and extra products. No dialogue, speech, singing or music; use quiet ambient room tone only.", "promptVersion": 3, "requiresDetail": true, "allowedSettings": {"framing": ["macro", "close_up"], "lighting": ["soft_studio", "bright_clean", "moody_cinematic"], "cameraAngle": ["top_down", "th